import{_ as t,a,b as r}from"./chunks/console-models.1j_Niwy1.js";import{_ as o}from"./chunks/console-usage.mPwN76Mj.js";import{_ as n,o as i,c as s,a0 as d}from"./chunks/framework.B7o6dWmz.js";const w=JSON.parse(`{"title":"NetonAPI 1.0.0: an AI API relay designed from the operator's side","description":"","frontmatter":{},"headers":[],"relativePath":"releases/1.0.0.md","filePath":"releases/1.0.0.md","lastUpdated":1794047970000}`),l={name:"releases/1.0.0.md"};function c(h,e,p,u,g,m){return i(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="netonapi-1-0-0-an-ai-api-relay-designed-from-the-operator-s-side" tabindex="-1">NetonAPI 1.0.0: an AI API relay designed from the operator&#39;s side <a class="header-anchor" href="#netonapi-1-0-0-an-ai-api-relay-designed-from-the-operator-s-side" aria-label="Permalink to &quot;NetonAPI 1.0.0: an AI API relay designed from the operator&#39;s side&quot;">​</a></h1><p>2026-11-07</p><p>NetonAPI is a self-hosted relay for large-model APIs: one key for OpenAI, Claude, Gemini, DeepSeek, Qwen, GLM, Kimi, Grok and more, billed per token, with an admin console and a user console included. Today we release 1.0.0.</p><h2 id="why-another-relay" tabindex="-1">Why another relay <a class="header-anchor" href="#why-another-relay" aria-label="Permalink to &quot;Why another relay&quot;">​</a></h2><p>Most open-source relays start from &quot;forward the request&quot; and bolt billing on as stacked ratios. Running a relay as a business is hard for other reasons: <strong>what each model sells for, what it costs, whether a request made money, whether a key-account discount loses money somewhere, and whether the user&#39;s bill matches the price they saw.</strong> NetonAPI was designed around those questions from the first line of code.</p><h3 id="_1-anchored-to-the-official-price" tabindex="-1">1. Anchored to the official price <a class="header-anchor" href="#_1-anchored-to-the-official-price" aria-label="Permalink to &quot;1. Anchored to the official price&quot;">​</a></h3><p>Customers compare against the official price (&quot;Claude is $3 officially, 70% here&quot;). NetonAPI writes the sale price as &quot;official × markup&quot;, and discounts for a group or a single key account as &quot;N% of official&quot; — when the official price changes, they follow, and the promise stays true. No layers of ratios to convert.</p><h3 id="_2-every-channel-has-a-real-cost-and-loss-making-prices-can-t-be-saved" tabindex="-1">2. Every channel has a real cost, and loss-making prices can&#39;t be saved <a class="header-anchor" href="#_2-every-channel-has-a-real-cost-and-loss-making-prices-can-t-be-saved" aria-label="Permalink to &quot;2. Every channel has a real cost, and loss-making prices can&#39;t be saved&quot;">​</a></h3><p>Each upstream channel records its cost: a discount off the official price, pulled automatically from an upstream relay&#39;s price API, or entered per model; unusual cost changes are held until an operator confirms them. Every price — site, group, or a user&#39;s negotiated price — is checked against <strong>every channel that would actually serve it</strong> before saving, and <strong>below cost is refused</strong>. The pricing health check lists the worst margin of each group × channel combination; the profit dashboard shows revenue, cost and losses by group and channel.</p><h3 id="_3-the-unit-price-shown-is-the-unit-price-charged" tabindex="-1">3. The unit price shown is the unit price charged <a class="header-anchor" href="#_3-the-unit-price-shown-is-the-unit-price-charged" aria-label="Permalink to &quot;3. The unit price shown is the unit price charged&quot;">​</a></h3><p>Charge = tokens × the unit price the user sees in the console, rounded up per component; the pricing page, the console and the bill are the same number and can be reconciled request by request. When upstream usage data is irregular (more cached tokens than input, missing cache price…), the conservative reading is used — never undercharging, never giving cache hits away.</p><h3 id="_4-a-two-phase-ledger" tabindex="-1">4. A two-phase ledger <a class="header-anchor" href="#_4-a-two-phase-ledger" aria-label="Permalink to &quot;4. A two-phase ledger&quot;">​</a></h3><p>Each request reserves an upper bound first and settles on actual usage, with the price snapshot frozen per request — changing prices mid-flight affects nothing in progress. After a crash the ledger recovers automatically; anything unclear goes to a manual review queue, <strong>never auto-refunded, never double-charged</strong>.</p><h3 id="_5-an-admin-console-built-for-operators" tabindex="-1">5. An admin console built for operators <a class="header-anchor" href="#_5-an-admin-console-built-for-operators" aria-label="Permalink to &quot;5. An admin console built for operators&quot;">​</a></h3><ul><li><strong>Negotiated pricing</strong>: find a user, set &quot;N% of official&quot; per model (or in bulk), and see their price and your margin live.</li><li><strong>Billing group decided by API key</strong>: dedicated lines and special rates attach to a specific key and take effect immediately.</li><li><strong>Menu- and button-level permissions</strong> with four preset roles: gateway ops, finance, support, read-only.</li><li><strong>API keys are shown only once</strong> at creation and only their hash is stored; upstream keys are encrypted; payment secrets are write-only.</li></ul><h2 id="a-quick-look" tabindex="-1">A quick look <a class="header-anchor" href="#a-quick-look" aria-label="Permalink to &quot;A quick look&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Overview: revenue, cost, margin</th><th>Negotiated pricing: per-model discounts with live margin</th></tr></thead><tbody><tr><td><img src="'+t+'" alt="Overview"></td><td><img src="'+a+'" alt="Negotiated pricing"></td></tr><tr><td><strong>User console: models and prices</strong></td><td><strong>User console: usage and balance</strong></td></tr><tr><td><img src="'+r+'" alt="Models and prices"></td><td><img src="'+o+'" alt="Usage"></td></tr></tbody></table><h2 id="what-1-0-0-includes" tabindex="-1">What 1.0.0 includes <a class="header-anchor" href="#what-1-0-0-includes" aria-label="Permalink to &quot;What 1.0.0 includes&quot;">​</a></h2><ul><li><strong>Endpoints</strong>: OpenAI (Chat Completions, Responses, Embeddings, Images, Audio, Rerank), Anthropic Messages and native Gemini, converted between inbound and upstream protocols <strong>in any direction</strong> (tool calls, images, thinking and cache usage preserved), streaming and non-streaming; Claude Code and official SDKs work as is.</li><li><strong>Upstreams</strong>: OpenAI-compatible (including other relays), Azure OpenAI, Anthropic, Gemini, AWS Bedrock, Vertex AI.</li><li><strong>Routing and failover</strong>: priority + weight, automatic failover (including when an upstream reports &quot;no such model&quot;), key suspension and cooldown, scheduled probes, long answers never truncated.</li><li><strong>Billing</strong>: per token, per call and long-context tiers; cache reads and writes priced separately; site, group and negotiated prices, reconcilable per request.</li><li><strong>Money</strong>: manual top-up, redemption codes, online payment (Alipay and aggregated providers, extensible), full balance ledger.</li><li><strong>Operations</strong>: overview (revenue / cost / margin, daily trend, top models and users, channel health), price source sync and calibration, price history, usage logs, settlement review, Prometheus metrics.</li><li><strong>Users</strong>: sign-up and login (password, SMS code), self-service API keys (budget, expiry, model scope, IP allowlist), usage and billing, price list, integration guide.</li><li><strong>Deployment</strong>: <strong>a single native executable</strong> compiled with Kotlin/Native, no JVM at runtime; PostgreSQL (Redis optional). The framework (Neton 1.1.0), neton-ai 0.1.0 and geolite4k 0.1.2 come from Maven Central; everything builds from public sources.</li></ul><h2 id="compared-with-mainstream-open-source-relays" tabindex="-1">Compared with mainstream open-source relays <a class="header-anchor" href="#compared-with-mainstream-open-source-relays" aria-label="Permalink to &quot;Compared with mainstream open-source relays&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>NetonAPI 1.0</th><th>new-api</th><th>one-api</th></tr></thead><tbody><tr><td>Pricing</td><td>Anchored to official price, &quot;N% of official&quot;</td><td>Model × completion × group ratios</td><td>Group × model × completion ratios</td></tr><tr><td>Per-user × per-model negotiated price</td><td>Yes</td><td>Via user group ratio</td><td>Via user group ratio</td></tr><tr><td>Real channel cost / margin protection</td><td>Yes, below cost can&#39;t be saved</td><td>Not covered in public docs</td><td>Not covered in public docs</td></tr><tr><td>Shown unit price = charged unit price</td><td>Yes, reconcilable per request</td><td>Pre-deduct, then refund or top up</td><td>Pre-deduct, then settle</td></tr><tr><td>Ledger</td><td>Two-phase reserve → settle, crash recovery</td><td>Pre-deduct + settle</td><td>Pre-deduct + settle</td></tr><tr><td>API keys</td><td>Shown once, hash only</td><td>Viewable any time</td><td>Viewable any time</td></tr><tr><td>Protocol conversion</td><td>OpenAI / Anthropic / Gemini, any direction</td><td>Four text protocols</td><td>Unified to OpenAI</td></tr><tr><td>Upstream types</td><td>6 (covering every OpenAI-compatible site)</td><td>Dozens</td><td>30+</td></tr><tr><td>Task APIs (MJ, video)</td><td>Not yet</td><td>Yes</td><td>No</td></tr><tr><td>Deployment</td><td>Single native executable, PostgreSQL</td><td>Go / Docker, several databases</td><td>Go / Docker, SQLite / MySQL</td></tr></tbody></table><p>See the <a href="/compare">full comparison</a>. The new-api and one-api columns are based on their public documentation (2026-11).</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><p>Stated plainly:</p><ul><li>No task-style APIs such as Midjourney, Suno or video generation; fewer upstream types than new-api (though any OpenAI-compatible site works).</li><li>No third-party login (GitHub, OIDC…) or two-factor authentication for users yet.</li><li>PostgreSQL only.</li><li>The Docker / compose path has not yet been run on a real Docker host; the bare-metal install in DEPLOY.md is recommended.</li></ul><h2 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h2><ul><li>Server: <a href="https://github.com/netonapi/netonapi" target="_blank" rel="noreferrer">netonapi/netonapi</a></li><li>Admin console: <a href="https://github.com/netonapi/netonapi-admincp" target="_blank" rel="noreferrer">netonapi/netonapi-admincp</a></li><li>Website (portal, pricing page, user console): <a href="https://github.com/netonapi/netonapi-web" target="_blank" rel="noreferrer">netonapi/netonapi-web</a></li><li>Deployment guide and end-to-end tests: <a href="https://github.com/zoujiaqing/nanogate/blob/main/DEPLOY.md" target="_blank" rel="noreferrer">DEPLOY.md</a></li></ul><p>License: Apache-2.0.</p>',28)])])}const k=n(l,[["render",c]]);export{w as __pageData,k as default};
